def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    values = sorted(set(a))
    ranks = {value: i + 1 for i, value in enumerate(values)}
    tree = [0] * (len(values) + 1)
    size = len(values)
    result = []

    for i, value in enumerate(a):
        rank = ranks[value]
        count_leq = 0
        index = rank
        while index:
            count_leq += tree[index]
            index -= index & -index

        result.append(min(i, k) - count_leq)

        index = rank
        while index <= size:
            tree[index] += 1
            index += index & -index

        if i >= k:
            index = ranks[a[i - k]]
            while index <= size:
                tree[index] -= 1
                index += index & -index

    return result
